//!
//! The report's own words, lifted mechanically out of the Swift catalog
//! (`L10nServices` + `L10nScripts`). Only the functions the report actually
//! calls are here, the same deliberate narrowing `dns_l10n.rs` made: the
//! agent is a musl binary that cannot link the Swift package, so this text
//! is duplicated on purpose and the duplication is caught by fixtures.
//!
//! en and ru are pinned byte-for-byte by the report fixtures. The other
//! seven languages are only as right as the extraction — which is why the
//! extraction is a committed script and not typed prose.

use crate::dns_records::Language;

/// `L10nScripts.pad` — the report's labels are column-aligned to 16 so the
/// values line up. Swift counts Characters (grapheme clusters); for these
/// labels — plain words and CJK, no combining marks — `chars()` is the same
/// count, and the fixtures pin it in both en and ru.
pub fn pad_label(label: &str) -> String {
    let width = 16;
    let n = label.chars().count();
    if n >= width {
        format!("{label} ")
    } else {
        format!("{label}{}", " ".repeat(width - n))
    }
}

