/// Says which clients can actually USE the filter. The Swift side's
/// `L10nServices.piholeServesNetworkNote` — kept word for word, because the
/// two halves of this port are checked against each other's OUTPUT.
pub fn pihole_serves_network_note(l: Language) -> String {
    match l {
        Language::En => "DNS is served to the whole network on port 53 — point your router or your devices at this server's address. Make sure port 53 is not reachable from the internet.".to_string(),
        Language::De => "DNS wird auf Port 53 im gesamten Netzwerk bereitgestellt — richten Sie Ihren Router oder Ihre Geräte auf die Adresse dieses Servers. Stellen Sie sicher, dass Port 53 aus dem Internet nicht erreichbar ist.".to_string(),
        Language::Fr => "Le DNS est servi à tout le réseau sur le port 53 — pointez votre routeur ou vos appareils vers l'adresse de ce serveur. Assurez-vous que le port 53 n'est pas joignable depuis internet.".to_string(),
        Language::Es => "El DNS se sirve a toda la red en el puerto 53: apunte su router o sus dispositivos a la dirección de este servidor. Asegúrese de que el puerto 53 no sea accesible desde internet.".to_string(),
        Language::Ru => "DNS отдаётся всей сети на порт 53 — направьте роутер или устройства на адрес этого сервера. Убедитесь, что порт 53 недоступен из интернета.".to_string(),
        Language::Uk => "DNS віддається всій мережі на порт 53 — спрямуйте роутер або пристрої на адресу цього сервера. Переконайтеся, що порт 53 недоступний з інтернету.".to_string(),
        Language::It => "Il DNS è servito a tutta la rete sulla porta 53: punta il router o i dispositivi all'indirizzo di questo server. Assicurati che la porta 53 non sia raggiungibile da internet.".to_string(),
        Language::Ja => "DNS はポート 53 でネットワーク全体に提供されます — ルーターまたは各端末をこのサーバーのアドレスに向けてください。ポート 53 がインターネットから到達できないことを確認してください。".to_string(),
        Language::Zh => "DNS 在 53 端口向整个网络提供服务——请把路由器或各设备指向这台服务器的地址。请确认 53 端口无法从互联网访问。".to_string(),
    }
}

pub fn pihole_loopback_note(l: Language) -> String {
    match l {
        Language::En => "DNS answers on this machine only (127.0.0.1:53), so no open resolver is exposed. To serve the network, turn that on in the server's settings and reinstall — only do it where port 53 cannot be reached from the internet.".to_string(),
        Language::De => "DNS antwortet nur auf dieser Maschine (127.0.0.1:53), es wird also kein offener Resolver bereitgestellt. Um das Netzwerk zu bedienen, schalten Sie das in den Servereinstellungen ein und installieren Sie neu — nur dort, wo Port 53 aus dem Internet nicht erreichbar ist.".to_string(),
        Language::Fr => "Le DNS ne répond que sur cette machine (127.0.0.1:53) : aucun résolveur ouvert n'est exposé. Pour servir le réseau, activez-le dans les réglages du serveur et réinstallez — uniquement là où le port 53 est injoignable depuis internet.".to_string(),
        Language::Es => "El DNS responde solo en esta máquina (127.0.0.1:53), así que no se expone ningún resolutor abierto. Para servir a la red, actívelo en los ajustes del servidor y reinstale, solo donde el puerto 53 no sea accesible desde internet.".to_string(),
        Language::Ru => "DNS отвечает только на этой машине (127.0.0.1:53), поэтому открытого резолвера нет. Чтобы отдавать DNS сети, включите это в настройках сервера и переустановите — только там, где порт 53 недоступен из интернета.".to_string(),
        Language::Uk => "DNS відповідає лише на цій машині (127.0.0.1:53), тож відкритого резолвера немає. Щоб віддавати DNS мережі, увімкніть це в налаштуваннях сервера й перевстановіть — лише там, де порт 53 недоступний з інтернету.".to_string(),
        Language::It => "Il DNS risponde solo su questa macchina (127.0.0.1:53), quindi non viene esposto alcun resolver aperto. Per servire la rete, attivalo nelle impostazioni del server e reinstalla — solo dove la porta 53 non è raggiungibile da internet.".to_string(),
        Language::Ja => "DNS はこのマシン上（127.0.0.1:53）だけで応答するため、オープンリゾルバーは公開されません。ネットワークに提供するにはサーバー設定で有効にして再インストールしてください — ポート 53 がインターネットから到達できない場所でのみ行ってください。".to_string(),
        Language::Zh => "DNS 仅在本机（127.0.0.1:53）应答，因此不会暴露开放解析器。若要为网络提供服务，请在服务器设置中开启并重新安装——只在 53 端口无法从互联网访问的地方这样做。".to_string(),
    }
}

