pub fn mailcow_auto_cert_note(l: Language) -> String {
    match l {
        Language::En => "SMTP/IMAPS use a trusted TLS certificate automatically (synced from Caddy and refreshed on renewal). Right after setup it may briefly be self-signed until Caddy issues the certificate — usually a few minutes.".to_string(),
        Language::De => "SMTP/IMAPS verwenden automatisch ein vertrauenswürdiges TLS-Zertifikat (von Caddy übernommen und bei Erneuerung aktualisiert). Direkt nach der Einrichtung kann es kurz selbstsigniert sein, bis Caddy das Zertifikat ausgestellt hat — meist wenige Minuten.".to_string(),
        Language::Fr => "SMTP/IMAPS utilisent automatiquement un certificat TLS de confiance (repris de Caddy et actualisé au renouvellement). Juste après l'installation, il peut être brièvement auto-signé jusqu'à ce que Caddy émette le certificat — généralement quelques minutes.".to_string(),
        Language::Es => "SMTP/IMAPS usan automáticamente un certificado TLS de confianza (tomado de Caddy y actualizado al renovar). Justo tras la instalación puede ser autofirmado un momento hasta que Caddy emita el certificado — normalmente unos minutos.".to_string(),
        Language::Ru => "SMTP/IMAPS автоматически используют доверенный TLS-сертификат (берётся из Caddy и обновляется при продлении). Сразу после установки он может быть самоподписанным, пока Caddy не выпустит сертификат — обычно несколько минут.".to_string(),
        Language::Uk => "SMTP/IMAPS автоматично використовують довірений TLS-сертифікат (береться з Caddy й оновлюється при продовженні). Одразу після встановлення він може бути самопідписаним, доки Caddy не випустить сертифікат — зазвичай кілька хвилин.".to_string(),
        Language::It => "SMTP/IMAPS usano automaticamente un certificato TLS attendibile (preso da Caddy e aggiornato al rinnovo). Subito dopo l'installazione può essere autofirmato per poco, finché Caddy non emette il certificato — di solito pochi minuti.".to_string(),
        Language::Ja => "SMTP/IMAPS は信頼された TLS 証明書を自動的に使用します（Caddy から同期し、更新時にも反映）。設定直後は Caddy が証明書を発行するまで一時的に自己署名になることがあります（通常は数分）。".to_string(),
        Language::Zh => "SMTP/IMAPS 会自动使用受信任的 TLS 证书（从 Caddy 同步，续期时刷新）。刚安装后，在 Caddy 签发证书之前可能短暂为自签名——通常几分钟。".to_string(),
    }
}

