/// Ported from `L10nServices.n8nWebhooksPublicNote` — byte-identical by construction.
/// The one site in the catalog the admin guard does not cover whole.
pub fn n8n_webhooks_public_note(l: Language) -> String {
    match l {
        Language::En => "The editor is behind the admin guard like every other panel, but the /webhook/ and /webhook-test/ addresses answer the whole internet — that is what makes an incoming trigger work. Anyone who knows a webhook address can call it, so treat it as a password.".to_string(),
        Language::De => "Der Editor liegt wie jedes andere Panel hinter dem Admin-Schutz, aber die Adressen /webhook/ und /webhook-test/ antworten dem gesamten Internet — nur so funktioniert ein eingehender Ausloeser. Wer eine Webhook-Adresse kennt, kann sie aufrufen: behandeln Sie sie wie ein Passwort.".to_string(),
        Language::Fr => "L'editeur est derriere la protection d'administration comme tous les autres panneaux, mais les adresses /webhook/ et /webhook-test/ repondent a tout l'internet — c'est ce qui fait fonctionner un declencheur entrant. Quiconque connait une adresse de webhook peut l'appeler : traitez-la comme un mot de passe.".to_string(),
        Language::Es => "El editor esta detras de la proteccion de administracion como los demas paneles, pero las direcciones /webhook/ y /webhook-test/ responden a todo internet — es lo que hace funcionar un disparador entrante. Cualquiera que conozca una direccion de webhook puede llamarla: tratela como una contrasena.".to_string(),
        Language::Ru => "Редактор закрыт админ-гардом, как и остальные панели, но адреса /webhook/ и /webhook-test/ отвечают всему интернету — иначе входящий триггер не сработает. Кто знает адрес вебхука, тот может его дёрнуть: относитесь к нему как к паролю.".to_string(),
        Language::Uk => "Редактор закритий адмін-гардом, як і решта панелей, але адреси /webhook/ та /webhook-test/ відповідають усьому інтернету — інакше вхідний тригер не спрацює. Хто знає адресу вебхука, той може його смикнути: ставтеся до неї як до пароля.".to_string(),
        Language::It => "L'editor sta dietro la protezione di amministrazione come ogni altro pannello, ma gli indirizzi /webhook/ e /webhook-test/ rispondono a tutta la rete — e cio che fa funzionare un trigger in entrata. Chi conosce un indirizzo di webhook puo chiamarlo: trattalo come una password.".to_string(),
        Language::Ja => "エディターは他のパネルと同じく管理ガードの内側にありますが、/webhook/ と /webhook-test/ のアドレスはインターネット全体に応答します — 受信トリガーはそれで動きます。webhook のアドレスを知っている人は誰でも呼び出せるので、パスワードと同じように扱ってください。".to_string(),
        Language::Zh => "编辑器与其他面板一样处于管理防护之后，但 /webhook/ 和 /webhook-test/ 地址会响应整个互联网 — 传入触发器正是靠它工作。知道 webhook 地址的人都能调用它，请像对待密码一样对待它。".to_string(),
    }
}

